For context:[DevTeam] said: Writing the Flask application code in app.py for creating to-do lists.[DevTeam] called tool `write_file` with parameters: {'content': "from flask import Flask, render_template, request, redirect, url_for

app = Flask(__name__)

# In-memory database for lists and tasks
todo_lists = {}
counter = 1

@app.route('/')
def index():
    return render_template('index.html', todo_lists=todo_lists)

@app.route('/lists', methods=['POST'])
def create_list():
    global counter
    name = request.form.get('name')
    if name:
        list_id = str(counter)
        counter += 1
        todo_lists[list_id] = {'id': list_id, 'name': name, 'tasks': []}
    return redirect(url_for('index'))

if __name__ == '__main__':
    app.run(debug=True)
